#!/usr/bin/env node
import { writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { exceedsFailLevel, inspectPlans, PlanInputError, toJson, toMarkdown, toSarif, type RiskLevel } from './index.js';

function usage(): string {
  return `Usage: connector-impact-table-skill <plan...> [--format json|markdown|sarif] [--out path] [--fail-on low|medium|high]
`;
}

const args = process.argv.slice(2);
if ((args.length === 1 && args[0] === '--help') || args.length === 0) {
  process.stdout.write(usage());
  process.exit(0);
}

let format: 'json' | 'markdown' | 'sarif' = 'json';
let out: string | undefined;
let failOn: RiskLevel | undefined;
const paths: string[] = [];
const failLevels: RiskLevel[] = ['low', 'medium', 'high'];

function optionValue(option: string, index: number): string {
  const value = args[index + 1];
  if (!value || value.startsWith('--')) {
    process.stderr.write(`Error: ${option} requires a value\n${usage()}`);
    process.exit(2);
  }
  return value;
}

function usageError(message: string): never {
  process.stderr.write(`Error: ${message}\n${usage()}`);
  process.exit(2);
}

function ioError(operation: 'read plan' | 'write report', path: string, error: unknown): never {
  const code = typeof error === 'object' && error !== null && 'code' in error &&
    typeof error.code === 'string' ? ` (${error.code})` : '';
  process.stderr.write(`Error: unable to ${operation} "${path}"${code}\n`);
  process.exit(2);
}

for (let i = 0; i < args.length; i += 1) {
  const arg = args[i];
  if (arg === '--format') {
    const value = optionValue(arg, i++);
    if (value !== 'json' && value !== 'markdown' && value !== 'sarif') usageError(`invalid --format value: ${value}`);
    format = value;
  } else if (arg === '--out') {
    out = optionValue(arg, i++);
  } else if (arg === '--fail-on') {
    const value = optionValue(arg, i++);
    if (!failLevels.includes(value as RiskLevel)) usageError(`invalid --fail-on value: ${value}`);
    failOn = value as RiskLevel;
  } else if (arg.startsWith('-')) usageError(`unknown option: ${arg}`);
  else paths.push(arg);
}

if (!paths.length) usageError('at least one plan path is required');
if (out && paths.some((path) => resolve(path) === resolve(out))) {
  usageError('--out must not resolve to an input plan path');
}

try {
  let report;
  try {
    report = await inspectPlans(paths, new Date(0).toISOString());
  } catch (error) {
    if (error instanceof PlanInputError) throw error;
    const failedPath = typeof error === 'object' && error !== null && 'path' in error &&
      typeof error.path === 'string' ? error.path : paths[0];
    ioError('read plan', failedPath, error);
  }

  const rendered = format === 'markdown' ? toMarkdown(report) : format === 'sarif' ? toSarif(report) : toJson(report);
  if (out) {
    try {
      await writeFile(out, rendered, 'utf8');
    } catch (error) {
      ioError('write report', out, error);
    }
  } else process.stdout.write(rendered);
  if (failOn && exceedsFailLevel(report, failOn)) process.exit(1);
} catch (error) {
  if (error instanceof PlanInputError) usageError(error.message);
  throw error;
}

import { readFile } from 'node:fs/promises';
import { basename, extname } from 'node:path';
import { buildImpactReport } from './impact.js';
import { parsePlanEntries } from './parser.js';

export async function inspectPlans(paths: string[], now = '1970-01-01T00:00:00.000Z') {
  const entries = [];
  for (const path of paths) {
    const text = await readFile(path, 'utf8');
    const source = basename(path);
    const sourceId = source.slice(0, -extname(source).length) || source;
    entries.push(...parsePlanEntries(source, text).map((entry) => ({ ...entry, sourceId })));
  }
  const reserved = new Set(entries.filter((entry) => entry.explicitId).map((entry) => entry.action.id));
  const used = new Set<string>();
  const actions = entries.map(({ action, explicitId, sourceId }) => {
    const base = explicitId ? action.id : `${sourceId}-${action.id}`;
    let id = base;
    let suffix = 2;
    while (used.has(id) || (!explicitId && reserved.has(id))) id = `${base}-${suffix++}`;
    used.add(id);
    return { ...action, id };
  });
  return buildImpactReport(paths.map((path) => basename(path)), actions, now);
}

export { parsePlan, PlanInputError } from './parser.js';
export { scoreAction, buildImpactReport } from './impact.js';
export { toJson, toMarkdown, toSarif, exceedsFailLevel } from './report.js';
export type { ConnectorAction, ImpactReport, ImpactRow, RiskLevel } from './types.js';
